using System;using UnityEngine;using TMPro;using DG.Tweening;using LWS.TruckSports;
namespace LWS.TruckPoker {
// Presentation over an already authoritative deal. Never reads or writes private
// card values, deck order, bets, pots or awards. Every travelling card is a back.
public sealed class PokerMobileDealer:MonoBehaviour {
 public PokerMatch match;public Transform vehicle,hand;public Transform[] transit;public TMP_Text pacingLabel;public GameObject skipButton;public float driveSpeed=9;public Vector2 tabletopRadius=new Vector2(4.9f,3.1f);public AudioClip[] giggles;public int Reactions{get;private set;}public int GigglesPlayed{get;private set;}AudioSource giggle;bool skipping;public readonly int[] Delivered=new int[8];
 public bool Active{get;private set;}public int Hand{get;private set;}public int DeliveredCards{get;private set;}public float Travelled{get;private set;}public int CurrentSeat{get;private set;}=-1;
 public bool Quick=>SportsPrefs.GetInt("TruckPoker.DealerPacing.v1",0)==1;
 sealed class Wheel {public Transform mesh;public Quaternion rest;public Vector3 position,center,pivot,axis,up;public float radius,spin,sign;public bool front;}Wheel[] wheels;Vector3 lastForward;
 Sequence route;Vector3 home,last;Quaternion homeRotation,handRest;int deliveredMask;bool initialized;
 void Initialize(){if(initialized)return;initialized=true;home=vehicle.position;homeRotation=vehicle.rotation;handRest=hand.localRotation;last=home;lastForward=vehicle.forward;var found=new System.Collections.Generic.List<Wheel>();foreach(var f in vehicle.GetComponentsInChildren<MeshFilter>(true)){if(!f.name.StartsWith("Whl HD"))continue;var b=f.sharedMesh.bounds;int axis=b.size.x<b.size.y?(b.size.x<b.size.z?0:2):(b.size.y<b.size.z?1:2);var vector=axis==0?Vector3.right:axis==1?Vector3.up:Vector3.forward;float radius=0;for(int n=0;n<3;n++)if(n!=axis){var radial=Vector3.zero;radial[n]=b.extents[n];radius=Mathf.Max(radius,f.transform.TransformVector(radial).magnitude);}var t=f.transform;var center=Vector3.Scale(t.localScale,b.center);found.Add(new Wheel{mesh=t,rest=t.localRotation,position=t.localPosition,center=center,pivot=t.localPosition+t.localRotation*center,axis=vector,up=t.parent.InverseTransformDirection(Vector3.up),radius=Mathf.Max(.1f,radius),sign=Vector3.Dot(t.TransformDirection(vector),vehicle.right)>=0?1:-1,front=f.name.Contains(" FL")||f.name.Contains(" FR")});}wheels=found.ToArray();}
 public void Begin(){Initialize();Stop();Hand=match.Table.HandNumber;deliveredMask=DeliveredCards=0;Travelled=0;Reactions=GigglesPlayed=0;Array.Clear(Delivered,0,Delivered.Length);Active=true;CurrentSeat=-1;int thisHand=Hand;route=DOTween.Sequence();route.SetAutoKill(true);route.timeScale=Quick?3:1;route.Append(hand.DOLocalRotate(new Vector3(-12,18,12),.16f).SetLoops(4,LoopType.Yoyo));route.Append(vehicle.DOMove(new Vector3(0,home.y,tabletopRadius.y),.35f).SetEase(Ease.InOutSine));float angle=0;
  for(int offset=1;offset<=match.setup.count;offset++){int seat=(match.Table.Button+offset)%match.setup.count;if(!match.Table.IsInHand(seat))continue;float target=Mathf.Atan2(match.avatars[seat].position.x/12,match.avatars[seat].position.z/9)*Mathf.Rad2Deg;target=angle+Mathf.Repeat(target-angle,360);AppendDrive(angle,target);angle=target;int who=seat;route.AppendCallback(()=>CurrentSeat=who);var targetRotation=Quaternion.LookRotation(new Vector3(Mathf.Sin(angle*Mathf.Deg2Rad),0,Mathf.Cos(angle*Mathf.Deg2Rad)));route.Append(vehicle.DORotateQuaternion(targetRotation,.2f).SetEase(Ease.OutSine));
   route.AppendCallback(()=>React());
   route.Append(vehicle.DORotateQuaternion(targetRotation*Quaternion.Euler(0,6,7),.13f).SetLoops(4,LoopType.Yoyo).SetEase(Ease.InOutSine));
   route.Append(vehicle.DORotateQuaternion(targetRotation,.1f));
   for(int n=0;n<2;n++){int card=n,index=seat*2+n;var moving=transit[index];route.Append(hand.DOLocalRotate(new Vector3(-18,-12,-8),.13f).SetEase(Ease.OutSine));route.AppendCallback(()=>{moving.SetPositionAndRotation(hand.TransformPoint(new Vector3(0,0,.7f)),Quaternion.Euler(90,0,0));moving.gameObject.SetActive(true);});var destination=match.presentation.seatCards[index].transform.position+Vector3.up*.08f;route.Append(moving.DOJump(destination,.38f,1,.22f).SetEase(Ease.OutQuad));route.Join(moving.DORotate(new Vector3(90,0,12),.22f));route.AppendCallback(()=>{moving.gameObject.SetActive(false);Deliver(thisHand,who,card);});route.Append(hand.DOLocalRotateQuaternion(handRest,.12f));}
  }
  AppendDrive(angle,angle+Mathf.Repeat(-angle,360));route.Append(vehicle.DOMove(home,.35f).SetEase(Ease.InOutSine));route.Join(vehicle.DORotateQuaternion(homeRotation,.35f));route.OnComplete(()=>{route=null;Active=false;CurrentSeat=-1;hand.localRotation=handRest;match.DealerFinished();});
 }
 void AppendDrive(float from,float until){float delta=until-from;if(delta<.01f)return;float cursor=from;route.Append(DOTween.To(()=>cursor,value=>{cursor=value;float a=value*Mathf.Deg2Rad;vehicle.SetPositionAndRotation(new Vector3(Mathf.Sin(a)*tabletopRadius.x,home.y,Mathf.Cos(a)*tabletopRadius.y),Quaternion.LookRotation(new Vector3(Mathf.Cos(a)*tabletopRadius.x,0,-Mathf.Sin(a)*tabletopRadius.y)));},until,Mathf.Max(.12f,delta*Mathf.Deg2Rad*(tabletopRadius.x+tabletopRadius.y)*.5f/driveSpeed)).SetEase(Ease.InOutSine));}
 void Deliver(int handNumber,int seat,int card){if(!Active||handNumber!=Hand)return;int bit=1<<(seat*2+card);if((deliveredMask&bit)!=0)return;deliveredMask|=bit;Delivered[seat]++;DeliveredCards++;match.DealerPresentationChanged();match.feedback.Play(2,0,true);}
 void React(){if(skipping||!Active)return;Reactions++;if(giggles==null||giggles.Length==0||match.settings.master<=0||match.settings.sfx<=0)return;if(giggle==null){giggle=vehicle.gameObject.AddComponent<AudioSource>();giggle.playOnAwake=false;giggle.spatialBlend=1;giggle.dopplerLevel=0;giggle.minDistance=6;giggle.maxDistance=40;giggle.rolloffMode=AudioRolloffMode.Logarithmic;}giggle.Stop();giggle.clip=giggles[(Hand+CurrentSeat)%giggles.Length];giggle.pitch=1.06f;giggle.volume=match.settings.sfx*.45f;giggle.Play();GigglesPlayed++;}
 public void PauseVoice(bool pause){if(giggle==null)return;if(pause)giggle.Pause();else giggle.UnPause();}
 public void StopVoice(){if(giggle!=null)giggle.Stop();}
 public void Skip(){if(Active&&route!=null){skipping=true;StopVoice();try{route.Complete(true);}finally{skipping=false;}}}
 public void CyclePacing(){SportsPrefs.SetInt("TruckPoker.DealerPacing.v1",Quick?0:1);SportsPrefs.Save();if(route!=null)route.timeScale=Quick?3:1;RefreshLabel();}
 public void RefreshLabel(){if(pacingLabel==null)return;var button=pacingLabel.GetComponentInParent<Michsky.UI.Heat.ButtonManager>();string value="DEALER: "+(Quick?"QUICK":"CINEMATIC");if(button!=null){button.buttonText=value;button.UpdateUI();}else pacingLabel.text=value;}
 public void Stop(){StopVoice();route?.Kill();route=null;Active=false;CurrentSeat=-1;if(transit!=null)foreach(var card in transit)if(card!=null)card.gameObject.SetActive(false);if(initialized){vehicle.SetPositionAndRotation(home,homeRotation);hand.localRotation=handRest;}last=vehicle!=null?vehicle.position:Vector3.zero;if(wheels!=null)foreach(var wheel in wheels){wheel.spin=0;wheel.mesh.SetLocalPositionAndRotation(wheel.position,wheel.rest);}if(vehicle!=null)lastForward=vehicle.forward;}
 void LateUpdate(){if(giggle!=null)giggle.volume=match.settings.sfx*.45f;if(vehicle==null)return;if(Active){float distance=Vector3.Distance(last,vehicle.position);Travelled+=distance;float angle=Vector3.SignedAngle(lastForward,vehicle.forward,Vector3.up);float steer=Mathf.Clamp(Mathf.Atan(angle*Mathf.Deg2Rad*2.2f/Mathf.Max(.05f,distance))*Mathf.Rad2Deg,-25,25);foreach(var wheel in wheels){wheel.spin=(wheel.spin+distance/wheel.radius*Mathf.Rad2Deg*wheel.sign)%360;wheel.mesh.localRotation=Quaternion.AngleAxis(wheel.front?steer:0,wheel.up)*wheel.rest*Quaternion.AngleAxis(wheel.spin,wheel.axis);wheel.mesh.localPosition=wheel.pivot-wheel.mesh.localRotation*wheel.center;}}lastForward=vehicle.forward;last=vehicle.position;if(skipButton!=null)skipButton.SetActive(Active&&match.Live);}
 void OnDestroy(){StopVoice();route?.Kill();}
}
}
